/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var v = {};
  function phases(ph) { for (var i = 0; i < ph.length; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; } }

  phases([[0,10],[10,34],[34,54],[54,80]]);
  var nv = 0;
  for (var i = 0; i < 6; i++) { v['vp'+i] = p >= 11 + i * 3.6 ? 1 : 0; v['vr'+i] = p >= 12.5 + i * 3.6 ? 1 : 0; nv += v['vp'+i] + v['vr'+i]; }
  v.nv = nv;
  var ns = 0, np = 0;
  for (var i = 0; i < 6; i++) {
    var t = 35 + i * 3, f = lin([[t,0],[t+1.5,1]]); v['sh'+i] = f * out; if (p >= t) ns++;
    var t2 = 55 + i * 3.5, g = lin([[t2,0],[t2+2,1]]);
    v['pl'+i] = 'opacity: ' + (g > 0.01 ? 1 : 0) + '; transform: translateY(' + (-14 * (1 - g)).toFixed(1) + 'px);';
    v['kp'+i] = 'opacity: ' + (p >= t2 + 1.5 ? 1 : 0) + ';';
    if (p >= t2 + 2) np++;
  }
  v.ns = ns; v.np = np * 2;
  v.fin = (p >= 78 && p < 97) ? out : 0;

  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
